 <div className="stories" aria-label="Browse by home features">{['All homes','Modern','Character','Waterfront','Garden','Suite'].map((tag,i)=><button key={tag} className={`story ${category===tag?'active':''}`} aria-pressed={category===tag} onClick={()=>setCategory(tag)}><span className="ring">{i===0?<span className="all-ring"><Home size={26}/></span>:<img alt="" src={['','/photos/modern.jpg','/photos/garden.jpg','/photos/retreat.jpg','/photos/garden.jpg','/photos/interior.jpg'][i]}/>}</span>{tag}</button>)}</div>
 {view!=='nearby'&&view!=='community'&&<div className="filters"><button className="filter-pill" onClick={()=>show('preferences')}><MapPin size={13}/>{prefs.area||'Any neighbourhood'}<ChevronRight size={13}/></button><label className="sr-only" htmlFor="budget">Preferred maximum price</label><select id="budget" value={prefs.maxPrice} onChange={e=>changePrefs({...prefs,maxPrice:Number(e.target.value)})}><option value="0">Any budget</option><option value="1200000">Up to $1.2M</option><option value="1500000">Up to $1.5M</option><option value="1800000">Up to $1.8M</option><option value="2000000">Up to $2M</option><option value="2500000">Up to $2.5M</option></select><label className="sr-only" htmlFor="beds">Preferred minimum bedrooms</label><select id="beds" value={prefs.minBeds} onChange={e=>changePrefs({...prefs,minBeds:Number(e.target.value)})}>{[0,2,3,4,5].map(b=><option key={b} value={b}>{b?`${b}+ beds`:'Any beds'}</option>)}</select><button className="filter-tune" onClick={()=>show('preferences')} aria-label="More feed preferences"><SlidersHorizontal size={17}/></button></div>}
 <div className="result-info"><span>{visible.length} homes to explore{category!=='All homes'&&` · ${category}`}</span><div className="result-actions"><button className="map-view-button" onClick={()=>show('map')} aria-haspopup="dialog"><MapPin size={15}/> Map &amp; radius</button><label><ArrowDownUp size={12}/><select aria-label="Sort homes" value={sort} onChange={e=>setSort(e.target.value)}><option value="nearest">Nearest first</option><option value="for-you">For you</option><option value="low">Price: low first</option><option value="high">Price: high first</option></select></label></div></div>
 {view==='feed'&&searchArea&&<div className="radius-summary"><span><MapPin size={14}/> {searchArea.radiusKm} km search radius{searchArea.includeOutside?' · Occasional outside matches':' · Inside only'}</span><button className="text-button" onClick={()=>show('map')}>Adjust area</button><button className="text-button" onClick={()=>commit({...state,searchArea:null})}>Clear radius</button>{unknownLocations>0&&<small>{unknownLocations} {unknownLocations===1?'home has':'homes have'} no map location yet. <button onClick={()=>switchView('community')}>Browse seller listings</button></small>}</div>}
